const body = $json.body ?? $json;

// Meta Cloud API payload
const metaValue = body?.entry?.[0]?.changes?.[0]?.value;
const metaMsg = metaValue?.messages?.[0];
const metaText = metaMsg?.text?.body;
const metaFrom = metaMsg?.from;

// Legacy/Evolution payload fallback
const evolutionText = body?.data?.message?.text || body?.message;
const evolutionFrom = body?.data?.key?.remoteJid || body?.phone;

const message = metaText || evolutionText || '';
const rawPhone = metaFrom || evolutionFrom || '';
const phone = String(rawPhone).replace(/[^0-9]/g, '');

if (!message || !phone) return [];

return [{ json: { raw: body, message, phone } }];

const input = $items('Parse Incoming', 0, 0)[0].json;
const historyRows = items.map(i => i.json);
const historyText = historyRows.map(h => `${h.role}: ${h.content}`).join('
');
const systemPrompt = `Voce e um classificador de intencoes para um salao de beleza. Retorne APENAS um JSON puro sem markdown.

Classifique a mensagem em UMA destas categorias EXATAS (use o valor exato, sem variacao):
- agendamento
- faq
- vendas
- reclamacao
- humano

Definicoes:
- agendamento: marcar, reagendar, cancelar, consultar horario, confirmar servico
- faq: perguntas sobre precos, endereco, horario de funcionamento, servicos, pagamento
- vendas: resposta a promocao, interesse em servico novo, pedir sugestao
- reclamacao: insatisfacao, problema com servico, critica
- humano: pedido por atendente humano, situacao ambigua, xingamento

Regras:
- Retorne SOMENTE JSON: {"intent": "<categoria>", "confidence": <0.0-1.0>}
- Use EXATAMENTE um dos 5 valores acima para intent
- Se confidence < 0.65, use intent "humano"
- Nunca responda ao cliente, apenas classifique`;
const userPrompt = `Mensagem: ${input.message}

Historico:
${historyText || 'sem historico'}

Retorne JSON com intent e confidence.`;
return [{
  json: {
    ...input,
    history: historyRows,
    system_prompt: systemPrompt,
    user_prompt: userPrompt
  }
}];

const source = $items('Build Router Prompt', 0, 0)[0].json;
const fallback = { intent: 'humano', confidence: 0.5, parse_error: true };
let text = '';
const raw = $json;
// TESS response format
if (raw.responses?.[0]?.output) text = raw.responses[0].output;
// OpenAI fallback
if (!text && raw.choices?.[0]?.message?.content) text = raw.choices[0].message.content;
// Anthropic fallback
if (!text && Array.isArray(raw.content) && raw.content[0]?.text) text = raw.content[0].text;
// Extract JSON from markdown code block or raw JSON
const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/) || text.match(/(\{[\s\S]*?\})/);
if (jsonMatch) text = jsonMatch[1].trim();
let parsed = fallback;
try {
  parsed = { ...fallback, ...JSON.parse(text), parse_error: false };
} catch (e) {
  parsed = fallback;
}
// Normalize intent variations to canonical names
const intentMap = {
  'agendar_servico': 'agendamento', 'agendar': 'agendamento', 'agendamento_servico': 'agendamento',
  'reagendar': 'agendamento', 'cancelar': 'agendamento', 'booking': 'agendamento',
  'pergunta': 'faq', 'duvida': 'faq', 'informacao': 'faq',
  'venda': 'vendas', 'promocao': 'vendas',
  'reclamação': 'reclamacao', 'complaint': 'reclamacao',
  'human': 'humano', 'atendente': 'humano'
};
const validIntents = ['agendamento', 'faq', 'vendas', 'reclamacao', 'humano'];
if (parsed.intent && !validIntents.includes(parsed.intent)) {
  parsed.intent = intentMap[parsed.intent] || 'humano';
}
if (!parsed.intent || typeof parsed.confidence !== 'number') parsed = fallback;
if (parsed.confidence < 0.65) parsed.intent = 'humano';
return [{ json: { ...source, intent: parsed.intent, confidence: parsed.confidence, parse_error: parsed.parse_error } }];

const data = $('Parse Intent').first().json;
return [{
  json: {
    workflow: 'WF-01-router',
    event: 'router_parse_error',
    status: 'error',
    error_code: 'intent_parse_failed',
    phone: data.phone,
    message: data.message,
    pediu: data.message,
    bot_action: 'nao conseguiu classificar a intencao da mensagem',
    result_label: 'nao entendeu o que a pessoa queria — escalando para humano',
    intent: data.intent,
    confidence: data.confidence,
    details: { parse_error: true }
  }
}];
